export type AblationMode = "baseline-fifo" | "treatment-type-aware";

export interface PairedCase {
  id: string;
  seed: number;
  prompt: string;
  expected: {
    answer: string;
    requiredFacts?: string[];
    forbiddenFacts?: string[];
  };
  metrics?: {
    tokens?: number;
    falseBlock?: boolean;
    safetyViolation?: boolean;
  };
}

export interface PairedAblationFixture {
  version: 1;
  preregistration: {
    primaryMetric: "passK";
    k: 3;
    repetitions: 3;
    alpha: 0.05;
    bootstrapResamples: 2000;
    latencyBudgetMs: number;
    tokenProxyBudget: number;
    maximumFalseBlockIncrease: number;
    maximumSafetyViolationIncrease: number;
  };
  cases: PairedCase[];
}

export interface RuntimeMemoryStore {
  runCase(input: {
    mode: AblationMode;
    case: PairedCase;
    repetition: number;
    seed: number;
  }): Promise<{
    success: boolean;
    answer?: string;
    retainedIds: string[];
    evictedIds: string[];
    latencyMs: number;
    tokenProxy: number;
    falseBlock: boolean;
    safetyViolation: boolean;
  }> | {
    success: boolean;
    answer?: string;
    retainedIds: string[];
    evictedIds: string[];
    latencyMs: number;
    tokenProxy: number;
    falseBlock: boolean;
    safetyViolation: boolean;
  };
}

export interface ConditionSummary {
  mode: AblationMode;
  successes: number;
  observations: number;
  successRate: number;
  passK: number;
  latencyMs: { p50: number; p95: number };
  tokenProxy: { mean: number; p95: number };
  falseBlocks: number;
  falseBlockRate: number;
  safetyViolations: number;
  safetyViolationRate: number;
}

export interface EffectEstimate {
  metric: string;
  treatmentMinusBaseline: number;
  confidenceInterval95: [number, number];
  unit: "proportion" | "milliseconds" | "tokens";
}

export interface PairedAblationReport {
  schemaVersion: 1;
  fixtureVersion: number;
  deterministic: true;
  conditions: [ConditionSummary, ConditionSummary];
  pairedEffects: EffectEstimate[];
  componentActivation: {
    verified: boolean;
    differingCaseIds: string[];
    baselineRetained: string[];
    baselineEvicted: string[];
    treatmentRetained: string[];
    treatmentEvicted: string[];
  };
  budgetEvaluation: {
    passed: boolean;
    regressions: string[];
  };
  disclosure: {
    internalOnly: true;
    changesProductDefaults: false;
    changesProductLocks: false;
    changesApproval: false;
  };
}

export function validatePairedAblationFixture(value: unknown): PairedAblationFixture;
export function runPairedAblation(input: {
  fixture: PairedAblationFixture;
  runtimeStore: RuntimeMemoryStore;
  bootstrapResamples?: number;
}): Promise<PairedAblationReport>;
export function summarizePairedAblation(value: unknown): PairedAblationReport;

